import{_ as i,c as a,o as t,ae as o}from"./chunks/framework.BR0IJ75L.js";const p=JSON.parse('{"title":"Neo UI Framework","description":"","frontmatter":{},"headers":[],"relativePath":"docs/nui/nui.md","filePath":"docs/nui/nui.md"}'),r={name:"docs/nui/nui.md"};function n(s,e,l,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="neo-ui-framework" tabindex="-1">Neo UI Framework <a class="header-anchor" href="#neo-ui-framework" aria-label="Permalink to &quot;Neo UI Framework&quot;">​</a></h1><p>A modern, production-ready React + TypeScript UI framework that provides complete coverage of the NetApp Neo API. Built with Vite, shadcn/ui, and Tailwind CSS, this framework is designed to be forked, white-labeled, and extended by our customers and partners.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Neo UI Framework is intended for developement deployments and white-labeled solutions. Please follow the guidelines below to your keep deployments secure.</p></div><p>This framework is used to build the UI shipped with NetApp Neo.</p><h2 id="🎯-overview" tabindex="-1">🎯 Overview <a class="header-anchor" href="#🎯-overview" aria-label="Permalink to &quot;🎯 Overview&quot;">​</a></h2><p>Neo UI Framework delivers a full-featured interface for managing NetApp Neo - the connector that enables organizations to securely connect their data to Gen AI platforms like Microsoft 365 Copilot without migration or policy changes.</p><h2 id="✨-key-features" tabindex="-1">✨ Key Features <a class="header-anchor" href="#✨-key-features" aria-label="Permalink to &quot;✨ Key Features&quot;">​</a></h2><ul><li><strong>Complete API Coverage</strong> - Full integration with Neo API including authentication, health monitoring, license management, user administration, share management, file operations, and activity logging</li><li><strong>Modern Tech Stack</strong> - Built with React 19, TypeScript 5.9, Vite 7, and Tailwind CSS 4</li><li><strong>Production Ready</strong> - Containerized deployment with nginx, Docker Compose support, and environment-based configuration</li><li><strong>White-Label Friendly</strong> - Easily customize branding, themes, and navigation to match your organization</li><li><strong>Type-Safe</strong> - Comprehensive TypeScript coverage with strict compiler options</li><li><strong>Responsive Design</strong> - Mobile-first approach with adaptive layouts and sidebar navigation</li><li><strong>Search &amp; Filter</strong> - Advanced file search across shares with comprehensive filtering options</li><li><strong>Real-time Updates</strong> - Live status monitoring and operation tracking</li></ul><h2 id="📚-key-features-by-page" tabindex="-1">📚 Key Features by Page <a class="header-anchor" href="#📚-key-features-by-page" aria-label="Permalink to &quot;📚 Key Features by Page&quot;">​</a></h2><h3 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h3><ul><li>System health metrics (CPU, memory, disk)</li><li>License status and expiration</li><li>Version information</li><li>Visual charts and statistics</li></ul><h3 id="shares" tabindex="-1">Shares <a class="header-anchor" href="#shares" aria-label="Permalink to &quot;Shares&quot;">​</a></h3><ul><li>List all configured SMB shares</li><li>Add/edit share configurations</li><li>Schedule automated crawls (cron expressions)</li><li>Start manual crawls</li><li>View detailed share information</li><li>Advanced configuration (Kerberos, realm, workgroup)</li></ul><h3 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h3><ul><li>Browse files across all shares</li><li>Advanced search with filters: <ul><li>File path and name</li><li>File type/extension</li><li>Date ranges (accessed, modified, created)</li><li>Size ranges</li><li>Sort by multiple fields</li></ul></li><li>View file metadata</li><li>Paginated results</li></ul><h3 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h3><ul><li>Real-time operation log</li><li>Filter by type and status</li><li>User attribution</li><li>Timestamp tracking</li></ul><h3 id="users" tabindex="-1">Users <a class="header-anchor" href="#users" aria-label="Permalink to &quot;Users&quot;">​</a></h3><ul><li>User management</li><li>Role-based access (admin/standard)</li><li>Password management</li><li>Active/inactive status</li></ul><h2 id="🤝-quick-start" tabindex="-1">🤝 Quick Start <a class="header-anchor" href="#🤝-quick-start" aria-label="Permalink to &quot;🤝 Quick Start&quot;">​</a></h2><p>Please see <a href="./QUICKSTART.html">QUICKSTART.md</a> to run Neo UI framework:</p><ul><li>from sources</li><li>with Docker/Podman</li></ul><h2 id="🤝-contributing" tabindex="-1">🤝 Contributing <a class="header-anchor" href="#🤝-contributing" aria-label="Permalink to &quot;🤝 Contributing&quot;">​</a></h2><p>We welcome contributions! Please see <a href="./CONTRIBUTOR.html">CONTRIBUTOR.md</a> for:</p><ul><li>Branch and workflow guidelines</li><li>Code standards and linting rules</li><li>Testing requirements</li><li>Pull request process</li></ul><h2 id="🔒-security" tabindex="-1">🔒 Security <a class="header-anchor" href="#🔒-security" aria-label="Permalink to &quot;🔒 Security&quot;">​</a></h2><p>Security is critical for production deployments. See <a href="./SECURITY.html">SECURITY.md</a> for:</p><ul><li>Vulnerability reporting process</li><li>Security best practices</li><li>Runtime hardening guidelines</li><li>Incident response procedures</li></ul><h2 id="📄-license" tabindex="-1">📄 License <a class="header-anchor" href="#📄-license" aria-label="Permalink to &quot;📄 License&quot;">​</a></h2><p>This project is part of the NetApp Innovation Labs initiative. Please refer to your organization&#39;s licensing policy when forking or redistributing.</p><h2 id="🆘-support" tabindex="-1">🆘 Support <a class="header-anchor" href="#🆘-support" aria-label="Permalink to &quot;🆘 Support&quot;">​</a></h2><p>For issues, questions, or feature requests:</p><ol><li>Check the <a href="https://github.com/NetApp/Innovation-Labs/blob/main/netapp-neo/FAQ.md" target="_blank" rel="noreferrer">FAQ</a></li><li>Review existing <a href="https://github.com/NetApp/Innovation-Labs/issues" target="_blank" rel="noreferrer">GitHub issues</a></li><li>Contact your NetApp representative</li></ol><h2 id="🎨-white-label-customization" tabindex="-1">🎨 White-Label Customization <a class="header-anchor" href="#🎨-white-label-customization" aria-label="Permalink to &quot;🎨 White-Label Customization&quot;">​</a></h2><h3 id="branding" tabindex="-1">Branding <a class="header-anchor" href="#branding" aria-label="Permalink to &quot;Branding&quot;">​</a></h3><ol><li><strong>Logo &amp; Title</strong> - Update <a href="./src/components/sidebars/sidebarheader.tsx.html"><code>src/components/sidebars/sidebarheader.tsx</code></a></li><li><strong>Favicon</strong> - Replace <code>public/netapp.svg</code></li><li><strong>Page Title</strong> - Edit <code>index.html</code></li></ol><h3 id="theming" tabindex="-1">Theming <a class="header-anchor" href="#theming" aria-label="Permalink to &quot;Theming&quot;">​</a></h3><ol><li><strong>Colors &amp; Variables</strong> - Modify CSS custom properties in <code>src/index.css</code></li><li><strong>Component Styles</strong> - Update Tailwind configuration in <code>tailwind.config.js</code></li><li><strong>Theme Toggle</strong> - Customize light/dark mode in <a href="./src/components/navs/theme-provider.tsx.html"><code>src/components/navs/theme-provider.tsx</code></a></li></ol><h3 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><ol><li><strong>Menu Items</strong> - Edit <a href="./src/components/sidebars/sidebar-content.tsx.html"><code>src/components/sidebars/sidebar-content.tsx</code></a></li><li><strong>Routes</strong> - Update routing in <a href="./src/App.tsx.html"><code>src/App.tsx</code></a></li><li><strong>Page Content</strong> - Modify components in <code>src/components/pages/</code></li></ol><h2 id="🔌-api-integration" tabindex="-1">🔌 API Integration <a class="header-anchor" href="#🔌-api-integration" aria-label="Permalink to &quot;🔌 API Integration&quot;">​</a></h2><p>The application uses <a href="./src/components/services/neo-api.tsx.html"><code>src/components/services/neo-api.tsx</code></a> as the single source of API communication. Key features:</p><ul><li><strong>Type-safe</strong> - Full TypeScript definitions for all endpoints</li><li><strong>Token-based auth</strong> - JWT bearer token authentication</li><li><strong>Error handling</strong> - Automatic session expiration detection</li><li><strong>Centralized config</strong> - Single base URL configuration</li></ul><p>All API types are exported from <a href="./src/components/services/models.tsx.html"><code>src/components/services/models.tsx</code></a>.</p><hr><p>Built with ❤️ by the NetApp Innovation Labs team</p>',46)])])}const m=i(r,[["render",n]]);export{p as __pageData,m as default};
